families.make_source:
def make(n):
    expr = "sin(x) + cos(y) * 2.5"
    return [[expr] for _ in range(n)]

def make(n):
    expr = 'x' + '+y' * n          # e.g. 'x+y+y+...+y' (≈2n characters)
    return [[expr]] * 8               # eight identical calls

def make(n):
    # generate n syntactically different but valid expressions: "x+0", "x+1", …
    return [[f"x+{i}"] for i in range(n)]

def make(n):
    exprs = [f'x{i}+y{i}' + '+z' * n for i in range(8)]
    return [[e] for e in exprs]
